#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <string>

std::uint32_t ExtractField(std::uint32_t reg, unsigned pos, unsigned width);
std::uint32_t InsertField(std::uint32_t reg, unsigned pos, unsigned width,
                          std::uint32_t value);

static std::uint32_t hex(const std::string& s)
{
    return static_cast<std::uint32_t>(std::strtoul(s.c_str(), nullptr, 16));
}

int main()
{
    std::string op;
    while (std::cin >> op)
    {
        std::string reg, value;
        unsigned pos, width;
        if (op == "ext")
        {
            std::cin >> reg >> pos >> width;
            std::printf("%08X\n", static_cast<unsigned>(ExtractField(hex(reg), pos, width)));
        }
        else
        {
            std::cin >> reg >> pos >> width >> value;
            std::printf("%08X\n", static_cast<unsigned>(
                InsertField(hex(reg), pos, width, hex(value))));
        }
    }
    return 0;
}

