"""Random registers, fields and values, including width 32 and values wider
than the field."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    lines = []
    for _ in range(8):
        width = rng.choice([1, 2, 3, 4, 5, 8, 12, 16, 31, 32])
        pos = rng.randint(0, 32 - width)
        reg = rng.getrandbits(32)
        if rng.random() < 0.5:
            lines.append("ext %08X %d %d" % (reg, pos, width))
        else:
            lines.append("ins %08X %d %d %08X" % (reg, pos, width, rng.getrandbits(32)))
    return {"name": "eight register operations #%d" % index,
            "stdin": "\n".join(lines) + "\n"}
